-- 1.3.11_OptionInfoNamesValues.sql
--
-- Apply OptionInfo nicknames, names, and balance columns from the 2026-09-28
-- OptionInfo export. HName is set to the same value as Name (English).
-- Existing rows are UPDATEd by OptionType; any missing OptionType is INSERTed.
-- No backup table.
--
-- Needs a gameserver restart (option tables load at boot).
-- Safe to run twice: every statement sets absolute values.
--
